/**
 * Generates the synthetic development fixture set.
 *
 * THE OUTPUT OF THIS SCRIPT IS FABRICATED. It is not Stone data and not
 * Agentbox data. It exists so the ingestion, query and route layers can be
 * built and tested before real seed data is available. Every generated file
 * carries a `_synthetic` banner saying so.
 *
 * Deterministic: a fixed seed means re-running produces byte-identical output,
 * so regenerating never shows up as noise in a diff.
 *
 *   node scripts/generate-dev-fixtures.mjs
 */

import { writeFileSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..');

const LISTING_COUNT = 500;
const OFFICE_COUNT = 76;
const AGENT_COUNT = 837;

/** mulberry32 — small deterministic PRNG. */
function makeRng(seed) {
  let a = seed >>> 0;
  return function rng() {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

const rng = makeRng(20260813);

const pick = (arr) => arr[Math.floor(rng() * arr.length)];
const int = (min, max) => min + Math.floor(rng() * (max - min + 1));
const chance = (p) => rng() < p;

/** Real Australian suburbs with their real postcodes, per state. */
const SUBURBS = [
  // NSW — Stone's heartland
  ['Balmain', 'NSW', '2041'], ['Manly', 'NSW', '2095'], ['Cronulla', 'NSW', '2230'],
  ['Newtown', 'NSW', '2042'], ['Bondi Junction', 'NSW', '2022'], ['Parramatta', 'NSW', '2150'],
  ['Chatswood', 'NSW', '2067'], ['Coogee', 'NSW', '2034'], ['Surry Hills', 'NSW', '2010'],
  ['Randwick', 'NSW', '2031'], ['Mosman', 'NSW', '2088'], ['Penrith', 'NSW', '2750'],
  ['Newcastle', 'NSW', '2300'], ['Wollongong', 'NSW', '2500'], ['Byron Bay', 'NSW', '2481'],
  ['Dee Why', 'NSW', '2099'], ['Marrickville', 'NSW', '2204'], ['Castle Hill', 'NSW', '2154'],
  ['Liverpool', 'NSW', '2170'], ['Orange', 'NSW', '2800'],
  // QLD
  ['New Farm', 'QLD', '4005'], ['Bulimba', 'QLD', '4171'], ['Southport', 'QLD', '4215'],
  ['Noosa Heads', 'QLD', '4567'], ['Toowong', 'QLD', '4066'], ['Cairns', 'QLD', '4870'],
  ['Broadbeach', 'QLD', '4218'], ['Ashgrove', 'QLD', '4060'],
  // ACT
  ['Braddon', 'ACT', '2612'], ['Kingston', 'ACT', '2604'], ['Belconnen', 'ACT', '2617'],
  ['Gungahlin', 'ACT', '2912'],
  // VIC
  ['Richmond', 'VIC', '3121'], ['Fitzroy', 'VIC', '3065'], ['St Kilda', 'VIC', '3182'],
  ['Brunswick', 'VIC', '3056'], ['Geelong', 'VIC', '3220'], ['Hawthorn', 'VIC', '3122'],
  ['Footscray', 'VIC', '3011'],
  // TAS
  ['Battery Point', 'TAS', '7004'], ['Sandy Bay', 'TAS', '7005'], ['Launceston', 'TAS', '7250'],
];

const STREETS = [
  'West Market Street', 'Darling Street', 'Beach Road', 'Victoria Avenue', 'Bay Street',
  'Church Street', 'Station Street', 'The Corso', 'Ocean Parade', 'Wattle Crescent',
  'Jacaranda Avenue', 'Mill Lane', 'Harbour View Road', 'Grevillea Street', 'Bourke Street',
  'Cliff Road', 'Sunnyside Terrace', 'Palm Grove', 'Marine Parade', 'Kembla Street',
];

const RESIDENTIAL_TYPES = ['House', 'Apartment', 'Townhouse', 'Villa', 'Unit', 'Duplex', 'Studio'];
const COMMERCIAL_TYPES = ['Office', 'Retail', 'Warehouse', 'Showroom'];
const RURAL_TYPES = ['Acreage', 'Farm', 'Lifestyle'];
const LAND_TYPES = ['Land'];

const FEATURES = [
  'Air Conditioning', 'Built-in Wardrobes', 'Dishwasher', 'Ensuite', 'Balcony',
  'Courtyard', 'Swimming Pool', 'Garage', 'Fireplace', 'Solar Panels',
  'Water Views', 'North Facing', 'Renovated Kitchen', 'Floorboards', 'Study',
];

const FIRST_NAMES = [
  'Jane', 'Michael', 'Priya', 'Tom', 'Sarah', 'Daniel', 'Mei', 'Liam', 'Ana', 'Josh',
  'Chloe', 'Ahmed', 'Grace', 'Ben', 'Isabella', 'Nathan', 'Sophie', 'Ryan', 'Aisha', 'Lucas',
];
const LAST_NAMES = [
  'Smith', 'Nguyen', 'Patel', 'O’Brien', 'Wilson', 'Chen', 'Taylor', 'Kaur', 'Brown',
  'Rossi', 'Hughes', 'Ali', 'Robinson', 'Lee', 'Murphy', 'Singh', 'Walker', 'Costa',
];

const BANNER =
  'SYNTHETIC DEVELOPMENT FIXTURE. Fabricated data, not Stone or Agentbox data. '
  + 'Generated by scripts/generate-dev-fixtures.mjs. Replace with the real seed '
  + 'export before anything reaches production.';

/** Listing IDs are strings. Mostly 7 digits, some 6 — never numbers. */
function makeListingId() {
  return chance(0.12) ? String(int(100000, 999999)) : String(int(1000000, 9999999));
}

function makeUniqueId() {
  if (chance(0.15)) return null;
  return chance(0.5)
    ? `100P${String(int(0, 999999)).padStart(6, '0')}`
    : `IRE${String(int(0, 9999999)).padStart(7, '0')}`;
}

function isoDate(daysAgo) {
  // Fixed epoch keeps output deterministic: 2026-08-13T00:00:00Z.
  const base = 1786924800000;
  return new Date(base - daysAgo * 86400000).toISOString();
}

function slugify(s) {
  return s.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');
}

// ---------------------------------------------------------------- offices ---

const offices = Array.from({ length: OFFICE_COUNT }, (_, i) => {
  const [suburb, state, postcode] = SUBURBS[i % SUBURBS.length];
  return {
    officeId: String(1000 + i),
    name: `Stone ${suburb}`,
    suburb,
    state,
    postcode,
    phone: `0${int(2, 8)} ${int(1000, 9999)} ${int(1000, 9999)}`,
    email: `${slugify(suburb)}@stone.example`,
  };
});

// ----------------------------------------------------------------- agents ---

const agents = Array.from({ length: AGENT_COUNT }, (_, i) => {
  const office = offices[i % offices.length];
  const firstName = pick(FIRST_NAMES);
  const lastName = pick(LAST_NAMES);
  return {
    agentId: String(50000 + i),
    firstName,
    lastName,
    fullName: `${firstName} ${lastName}`,
    officeId: office.officeId,
    phone: `04${int(10, 99)} ${int(100, 999)} ${int(100, 999)}`,
    email: `${slugify(`${firstName} ${lastName}`)}${i}@stone.example`,
    photoUrl: `https://picsum.photos/seed/agent${i}/200/200`,
  };
});

// --------------------------------------------------------------- listings ---

function makeListing(i) {
  const [suburb, state, postcode] = pick(SUBURBS);
  const office = pick(offices);
  const officeAgents = agents.filter((a) => a.officeId === office.officeId);

  const categoryRoll = rng();
  let category, propertyType;
  if (categoryRoll < 0.86) { category = 'residential'; propertyType = pick(RESIDENTIAL_TYPES); }
  else if (categoryRoll < 0.93) { category = 'commercial'; propertyType = pick(COMMERCIAL_TYPES); }
  else if (categoryRoll < 0.97) { category = 'rural'; propertyType = pick(RURAL_TYPES); }
  else { category = 'land'; propertyType = pick(LAND_TYPES); }

  const isRental = chance(0.28);
  const statusRoll = rng();
  let status;
  if (isRental) status = statusRoll < 0.78 ? 'forRent' : (statusRoll < 0.95 ? 'leased' : 'withdrawn');
  else if (statusRoll < 0.62) status = 'forSale';
  else if (statusRoll < 0.76) status = 'underOffer';
  else if (statusRoll < 0.96) status = 'sold';
  else status = 'withdrawn';

  const isLand = category === 'land';
  const bedrooms = isLand ? null : int(1, 6);
  const bathrooms = isLand ? null : int(1, 4);
  const carspaces = isLand ? null : int(0, 4);

  // Price. Rentals are weekly; sales are totals. Some vendors hide the price.
  let priceValue, priceDisplay, priceSearchable;
  if (isRental) {
    priceValue = int(9, 60) * 25;
    priceDisplay = `$${priceValue} per week`;
    priceSearchable = true;
  } else if (chance(0.11)) {
    priceValue = null;
    priceDisplay = chance(0.5) ? 'Contact Agent' : 'Auction';
    priceSearchable = false;
  } else {
    priceValue = int(28, 480) * 25000;
    priceDisplay = `$${priceValue.toLocaleString('en-AU')}`;
    priceSearchable = true;
  }

  const unitNumber = chance(0.3) ? String(int(1, 40)) : null;
  const streetNumber = String(int(1, 250));
  const street = pick(STREETS);
  const displayAddress = [
    unitNumber ? `${unitNumber}/${streetNumber}` : streetNumber,
    street,
  ].join(' ');

  const listedAt = isoDate(int(1, 400));
  const soldAt = (status === 'sold' || status === 'leased') ? isoDate(int(0, 60)) : null;

  const imageCount = isLand ? int(2, 6) : int(6, 24);
  const listingId = makeListingId();

  return {
    listingId,
    uniqueId: makeUniqueId(),
    slug: `${slugify(displayAddress)}-${slugify(suburb)}-${listingId}`,
    status,
    propertyType,
    category,
    unitNumber,
    streetNumber,
    street,
    suburb,
    state,
    postcode,
    displayAddress: `${displayAddress}, ${suburb} ${state} ${postcode}`,
    latitude: Number((-3400 - rng() * 900).toFixed(0)) / 100,
    longitude: Number((14500 + rng() * 600).toFixed(0)) / 100,
    priceValue,
    priceDisplay,
    priceSearchable,
    bedrooms,
    bathrooms,
    carspaces,
    landSize: chance(0.6) ? int(80, 1200) : null,
    landSizeUnit: category === 'rural' ? 'ha' : 'sqm',
    headline: `${bedrooms ? `${bedrooms} bedroom ` : ''}${propertyType.toLowerCase()} in ${suburb}`,
    description:
      `A ${propertyType.toLowerCase()} positioned in the heart of ${suburb}. `
      + 'This is placeholder copy in a synthetic development fixture and does not '
      + 'describe a real property.',
    features: Array.from({ length: int(2, 7) }, () => pick(FEATURES))
      .filter((v, idx, arr) => arr.indexOf(v) === idx),
    images: Array.from({ length: imageCount }, (_, n) => ({
      url: `https://picsum.photos/seed/listing${i}-${n}/1200/800`,
      order: n,
      caption: n === 0 ? 'Front elevation' : null,
    })),
    floorplans: chance(0.4)
      ? [{ url: `https://picsum.photos/seed/floorplan${i}/1000/700`, order: 0 }]
      : [],
    videoUrl: chance(0.18) ? `https://www.youtube.com/watch?v=synthetic${i}` : null,
    officeId: office.officeId,
    agentIds: Array.from(
      { length: Math.min(officeAgents.length, chance(0.35) ? 2 : 1) },
      (_, n) => officeAgents[(i + n) % officeAgents.length].agentId,
    ),
    listedAt,
    soldAt,
    modifiedAt: isoDate(int(0, 120)),
  };
}

const listings = Array.from({ length: LISTING_COUNT }, (_, i) => makeListing(i));

// The real feed contains genuine duplicate IDs, so the fixture must too —
// otherwise the idempotency gate in Task 4 passes for the wrong reason.
for (let i = 0; i < 6; i++) {
  const source = listings[int(0, listings.length - 1)];
  listings.push({ ...structuredClone(source), modifiedAt: isoDate(int(0, 5)) });
}

// ------------------------------------------------------------------ write ---

const write = (name, records) => {
  const path = join(ROOT, name);
  writeFileSync(path, `${JSON.stringify({ _synthetic: BANNER, records }, null, 2)}\n`);
  console.log(`${name}: ${records.length} records`);
};

write('seed-listings.dev.json', listings);
write('seed-offices.dev.json', offices);
write('seed-agents.dev.json', agents);

const uniqueIds = new Set(listings.map((l) => l.listingId));
console.log(
  `\n${listings.length} listing records, ${uniqueIds.size} distinct listingIds `
  + `(${listings.length - uniqueIds.size} duplicates, intentional).`,
);
